mkitem!{mkstruct!{# [doc = " The `Steal` struct is intended to used as the value for a query."] # [doc = " Specifically, we sometimes have queries (*cough* MIR *cough*)"] # [doc = " where we create a large, complex value that we want to iteratively"] # [doc = " update (e.g., optimize). We could clone the value for each"] # [doc = " optimization, but that'd be expensive. And yet we don't just want"] # [doc = " to mutate it in place, because that would spoil the idea that"] # [doc = " queries are these pure functions that produce an immutable value"] # [doc = " (since if you did the query twice, you could observe the mutations)."] # [doc = " So instead we have the query produce a `&'tcx Steal<mir::Body<'tcx>>`"] # [doc = " (to be very specific). Now we can read from this"] # [doc = " as much as we want (using `borrow()`), but you can also"] # [doc = " `steal()`. Once you steal, any further attempt to read will panic."] # [doc = " Therefore, we know that -- assuming no ICE -- nobody is observing"] # [doc = " the fact that the MIR was updated."] # [doc = ""] # [doc = " Obviously, whenever you have a query that yields a `Steal` value,"] # [doc = " you must treat it with caution, and make sure that you know that"] # [doc = " -- once the value is stolen -- it will never be read from again."] # [derive (Debug)] pub struct Steal < T > { value : RwLock < Option < T > > , }}}
mkitem!{mkimpl!{impl < T > Steal < T > { pub fn new (value : T) -> Self { Steal { value : RwLock :: new (Some (value)) } } # [track_caller] pub fn borrow (& self) -> MappedReadGuard < '_ , T > { let borrow = self . value . borrow () ; if borrow . is_none () { panic ! ("attempted to read from stolen value: {}" , std :: any :: type_name ::< T > ()) ; } ReadGuard :: map (borrow , | opt | opt . as_ref () . unwrap ()) } # [track_caller] pub fn get_mut (& mut self) -> & mut T { self . value . get_mut () . as_mut () . expect ("attempt to read from stolen value") } # [track_caller] pub fn steal (& self) -> T { let value_ref = & mut * self . value . try_write () . expect ("stealing value which is locked") ; let value = value_ref . take () ; value . expect ("attempt to steal from stolen value") } # [doc = " Writers of rustc drivers often encounter stealing issues. This function makes it possible to"] # [doc = " handle these errors gracefully."] # [doc = ""] # [doc = " This should not be used within rustc as it leaks information not tracked"] # [doc = " by the query system, breaking incremental compilation."] # [rustc_lint_untracked_query_information] pub fn is_stolen (& self) -> bool { self . value . borrow () . is_none () } }}}
mkitem!{mkimpl!{impl < CTX , T : HashStable < CTX > > HashStable < CTX > for Steal < T > { fn hash_stable (& self , hcx : & mut CTX , hasher : & mut StableHasher) { self . borrow () . hash_stable (hcx , hasher) ; } }}}